  cursor: pointer;
}
#tag-list li:hover { border-color: var(--accent); }
#tag-list li.active { background: var(--accent-soft); border-color: var(--accent); }
#tag-list .count { color: var(--muted); margin-left: 4px; font-size: 11px; }

#bookmark-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 12px; }

.card {
  display: flex;
  gap: 12px;
  padding: 14px 16px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
}
.card img.favicon { width: 20px; height: 20px; margin-top: 3px; flex-shrink: 0; border-radius: 4px; }
.card .body { flex: 1; min-width: 0; }
.card a.title { color: var(--text); font-weight: 600; text-decoration: none; font-size: 15px; }
.card a.title:hover { color: var(--accent); }
.card .url { color: var(--muted); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card .desc { font-size: 13px; margin: 6px 0 0; color: #c3c8d1; }
.card .card-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.card .card-tags span {
  font-size: 11px;
