:root {
  --bg: #0f1115;
  --panel: #181b22;
  --panel-2: #21252e;
  --border: #2b303b;
  --text: #e6e8ec;
  --muted: #8b93a1;
  --accent: #4f8cff;
  --accent-soft: #1d2c4d;
  --danger: #ff5c5c;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

header {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 24px;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--bg);
  z-index: 10;
}

header h1 { font-size: 20px; margin: 0; white-space: nowrap; }

#search {
  flex: 1;
  max-width: 520px;
  padding: 10px 14px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--panel);
  color: var(--text);
  font-size: 14px;
}

main {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 24px;
  padding: 24px;
  max-width: 1200px;
  margin: 0 auto;
}

aside { display: flex; flex-direction: column; gap: 24px; }

h2 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); margin: 0 0 12px; }

#add-form, #tag-filter {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
}

#add-form input, #add-form textarea {
  width: 100%;
  margin-bottom: 10px;
  padding: 9px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  resize: vertical;
}

button {
  width: 100%;
  padding: 10px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: white;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
button:hover { filter: brightness(1.1); }
button:disabled { opacity: 0.6; cursor: default; }

.status { font-size: 12px; color: var(--muted); margin: 8px 0 0; min-height: 14px; }
.status.error { color: var(--danger); }

#tag-list { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
#tag-list li {
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  font-size: 13px;
  cursor: pointer;
}
#tag-list li:hover { border-color: var(--accent); }
#tag-list li.active { background: var(--accent-soft); border-color: var(--accent); }
#tag-list .count { color: var(--muted); margin-left: 4px; font-size: 11px; }

#bookmark-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 12px; }

.card {
  display: flex;
  gap: 12px;
  padding: 14px 16px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
}
.card img.favicon { width: 20px; height: 20px; margin-top: 3px; flex-shrink: 0; border-radius: 4px; }
.card .body { flex: 1; min-width: 0; }
.card a.title { color: var(--text); font-weight: 600; text-decoration: none; font-size: 15px; }
.card a.title:hover { color: var(--accent); }
