.card .edit-form .status { margin: 0; }

.empty { color: var(--muted); text-align: center; padding: 40px; }

#active-filter { margin-bottom: 16px; min-height: 20px; color: var(--muted); font-size: 14px; }
#active-filter button {
  width: auto;
